using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows.Forms;
namespace ClassroomUpdater {
 internal static class Program {
  internal static string Host {
   get {
    string value=Environment.GetEnvironmentVariable("CLASSROOM_UPDATE_SERVER_URL")??"";
    if(string.IsNullOrWhiteSpace(value))return "";
    Uri root;if(!Uri.TryCreate(value,UriKind.Absolute,out root)||root.Scheme!="https"||root.AbsolutePath!="/"||root.UserInfo.Length>0||root.Query.Length>0||root.Fragment.Length>0)throw new InvalidDataException("更新服务必须是 HTTPS 根地址。");
    return value.Trim().TrimEnd('/');
   }
  }
  internal static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=100000};
  internal static Dictionary<string,object> Verify(string envelope){var outer=Json.Deserialize<Dictionary<string,object>>(envelope);string payload=(string)outer["payload"];using(var rsa=new RSACryptoServiceProvider()){rsa.FromXmlString(UpdateKey.Public);if(!rsa.VerifyData(Encoding.UTF8.GetBytes(payload),"SHA256",Convert.FromBase64String((string)outer["signature"])))throw new InvalidDataException("更新签名无效，未执行更新");}return Json.Deserialize<Dictionary<string,object>>(payload);}
  internal static Uri SafeUrl(string path){var u=new Uri(new Uri(Host),path);if(u.Scheme!="https"||u.Host!=new Uri(Host).Host||!u.AbsolutePath.StartsWith("/updates/"))throw new InvalidDataException("更新地址不在发布服务器内");return u;}
  internal static bool Allowed(string name,string product){if(name!=Path.GetFileName(name)||name.Contains(":")||name.Contains(".."))return false;if(product=="seewo")return name.StartsWith("奶龙课堂助教.")&&name.EndsWith(".exe");return new[]{"拍照解题助教.exe","拍照解题助教.exe.config","DirectShowLib.dll","Newtonsoft.Json.dll","WpfMath.dll","XamlMath.Shared.dll","课堂助教更新.exe","课堂助教更新.exe.config"}.Contains(name);}
  internal static List<string> Extract(string archive,string stage,string product){var result=new List<string>();long total=0;using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count>20)throw new InvalidDataException("更新文件数量异常");foreach(var item in zip.Entries){if(!Allowed(item.FullName,product)||result.Contains(item.FullName))throw new InvalidDataException("更新包含非程序文件");total+=item.Length;if(total>80000000)throw new InvalidDataException("更新文件异常大");item.ExtractToFile(Path.Combine(stage,item.FullName));result.Add(item.FullName);}}if(result.Count==0||!(product=="photo"?result.Contains("拍照解题助教.exe"):result.Any(x=>x.StartsWith("奶龙课堂助教."))))throw new InvalidDataException("缺少主程序");return result;}
  internal static Action<string,string> ApplyFault;
  internal static string FileHash(string file){if(!File.Exists(file))return "";using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}
  internal static string Apply(string stage,string target,List<string> files){
   if(files.Count==0||files.Distinct().Count()!=files.Count||files.Any(name=>!Allowed(name,"photo")))throw new InvalidDataException("更新包含非程序文件或重复文件");
   string backup=Path.Combine(target,"更新回退",DateTime.Now.ToString("yyyyMMdd_HHmmss")+"_"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(backup);var changed=new List<string>();var original=files.ToDictionary(name=>name,name=>FileHash(Path.Combine(target,name)));
   File.WriteAllText(Path.Combine(backup,"transaction.json"),Json.Serialize(original),Encoding.UTF8);
   try{
    foreach(string name in files){string dest=Path.Combine(target,name);if(File.Exists(dest)){File.Copy(dest,Path.Combine(backup,name));if(FileHash(Path.Combine(backup,name))!=original[name])throw new IOException("备份文件核验失败："+name);}File.Copy(Path.Combine(stage,name),dest+".update-new",true);}
    foreach(string name in files){string dest=Path.Combine(target,name),next=dest+".update-new";changed.Add(name);ApplyFault?.Invoke("replace",name);if(File.Exists(dest))File.Replace(next,dest,null);else File.Move(next,dest);}
    foreach(string name in files)if(FileHash(Path.Combine(target,name))!=FileHash(Path.Combine(stage,name)))throw new IOException("替换后的文件校验失败："+name);
    File.WriteAllText(Path.Combine(backup,"verified.success"),DateTime.UtcNow.ToString("o"),Encoding.UTF8);return backup;
   }catch(Exception failure){File.WriteAllText(Path.Combine(backup,"preserve.failed"),failure.Message,Encoding.UTF8);var errors=new List<Exception>();
    foreach(string name in Enumerable.Reverse(changed)){try{string old=Path.Combine(backup,name),dest=Path.Combine(target,name);if(FileHash(dest)==original[name])continue;ApplyFault?.Invoke("rollback",name);if(original[name].Length>0){if(!File.Exists(old)||FileHash(old)!=original[name])throw new IOException("备份校验失败："+name);File.Copy(old,dest,true);}else File.Delete(dest);}catch(Exception error){errors.Add(new IOException("恢复失败："+name,error));}}
    var unverified=new List<string>();foreach(string name in files)try{if(FileHash(Path.Combine(target,name))!=original[name])unverified.Add(name);}catch{unverified.Add(name);}
    if(unverified.Count>0)throw new IOException("更新中断，以下文件未能核验恢复："+string.Join("、",unverified)+"。不要启动当前混合版本；请从备份恢复："+backup,new AggregateException(new[]{failure}.Concat(errors)));
    throw new IOException("更新未完成，已逐项核验恢复旧程序；本机配置未参与替换。失败备份保留："+backup,failure);
   }finally{foreach(string name in files)try{File.Delete(Path.Combine(target,name)+".update-new");}catch{}}
  }
  static void RemoveManagedDirectory(string root,string folder){string fullRoot=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,full=Path.GetFullPath(folder);if(!full.StartsWith(fullRoot,StringComparison.OrdinalIgnoreCase)||!string.Equals(Directory.GetParent(full).FullName.TrimEnd(Path.DirectorySeparatorChar),fullRoot.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase)||(File.GetAttributes(full)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("缓存目录不在指定位置内或是目录链接");Directory.Delete(full,true);}
  internal static void CleanCache(string target,string active=null,string product=null,string current=null){string cache=Path.Combine(target,".update-cache");if(!Directory.Exists(cache))return;int verified=0;foreach(string folder in Directory.GetDirectories(cache).OrderByDescending(Directory.GetLastWriteTimeUtc)){Guid id;if(folder==active||!Guid.TryParseExact(Path.GetFileName(folder),"N",out id)||File.Exists(Path.Combine(folder,"preserve.failed")))continue;bool pending=File.Exists(Path.Combine(folder,"installer.pending"));if(pending&&product=="seewo"&&current!=null)try{string[] info=File.ReadAllLines(Path.Combine(folder,"release.version"));if(info.Length==2&&info[0]==product&&Version.Parse(current)>=Version.Parse(info[1])){File.WriteAllText(Path.Combine(folder,"verified.success"),current);pending=false;}}catch{}if(pending)continue;bool good=File.Exists(Path.Combine(folder,"verified.success"));if(good)verified++;if(good&&verified>3||Directory.GetLastWriteTimeUtc(folder)<DateTime.UtcNow.AddDays(-2))try{RemoveManagedDirectory(cache,folder);}catch{}}}
  internal static void TrimBackups(string target){string root=Path.Combine(target,"更新回退");if(!Directory.Exists(root))return;foreach(string folder in Directory.GetDirectories(root).Where(x=>System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(x),@"^\d{8}_\d{6}(?:_[a-f0-9]{8})?$" )).Where(x=>File.Exists(Path.Combine(x,"verified.success"))&&!File.Exists(Path.Combine(x,"preserve.failed"))).OrderByDescending(Directory.GetCreationTimeUtc).Skip(2))try{RemoveManagedDirectory(root,folder);}catch{}}
  [STAThread] static int Main(string[] args){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;string Arg(string key,string fallback=""){int i=Array.IndexOf(args,key);return i>=0&&i+1<args.Length?args[i+1]:fallback;}
   if(args.Contains("--probe")){try{string folder=Path.Combine(Path.GetTempPath(),"classroom-probe-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{using(var http=new HttpClient{Timeout=TimeSpan.FromSeconds(25)}){var feed=Verify(http.GetStringAsync(Host+"/updates/manifest.json?probe="+DateTime.UtcNow.Ticks).GetAwaiter().GetResult());var rows=new List<object>();foreach(var probeProduct in new[]{"photo","seewo"}){var release=(Dictionary<string,object>)feed[probeProduct];var bytes=http.GetByteArrayAsync(SafeUrl((string)release["url"])).GetAwaiter().GetResult();using(var sha=SHA256.Create())if(BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant()!=(string)release["sha256"]||bytes.Length!=Convert.ToInt64(release["bytes"]))throw new Exception("hash");string stage=Path.Combine(folder,probeProduct);Directory.CreateDirectory(stage);string zip=Path.Combine(stage,"release.zip");File.WriteAllBytes(zip,bytes);var files=Extract(zip,stage,probeProduct);rows.Add(new{probeProduct,version=release["version"],bytes=bytes.Length,files=files.Count,signature=true,hash=true,installed=false});}File.WriteAllText(Arg("--probe"),Json.Serialize(rows),Encoding.UTF8);}}finally{Directory.Delete(folder,true);}return 0;}catch(Exception e){File.WriteAllText(Arg("--probe"),e.ToString());return 7;}}
   if(args.Contains("--verify")){try{Verify(File.ReadAllText(Arg("--verify")));return 0;}catch{return 2;}}
   if(args.Contains("--lifecycle-child")){System.Threading.Thread.Sleep(1200);return 0;}
   if(args.Contains("--advanced-recovery-test"))return AdvancedRecoveryChecks.Run(Arg("--advanced-recovery-test"));
   if(args.Contains("--recovery-test"))return RecoveryChecks.Run(Arg("--recovery-test"));
   if(args.Contains("--self-test")){try{if(Allowed("../x.exe","photo")||Allowed("接口配置_仅自用.json","photo")||Allowed("remote.local.json","seewo"))return 3;try{Verify("{\"payload\":\"{}\",\"signature\":\"AA==\"}");return 4;}catch{}string root=Path.Combine(Path.GetTempPath(),"classroom-update-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string stage=Path.Combine(root,"stage"),testTarget=Path.Combine(root,"target");Directory.CreateDirectory(stage);Directory.CreateDirectory(testTarget);File.WriteAllText(Path.Combine(stage,"拍照解题助教.exe"),"new");File.WriteAllText(Path.Combine(testTarget,"拍照解题助教.exe"),"old");File.WriteAllText(Path.Combine(testTarget,"接口配置_仅自用.json"),"keep");Apply(stage,testTarget,new List<string>{"拍照解题助教.exe"});if(File.ReadAllText(Path.Combine(testTarget,"拍照解题助教.exe"))!="new"||File.ReadAllText(Path.Combine(testTarget,"接口配置_仅自用.json"))!="keep"||Directory.GetFiles(Path.Combine(testTarget,"更新回退"),"*.exe",SearchOption.AllDirectories).Length!=1)return 5;}finally{Directory.Delete(root,true);}return 0;}catch{return 9;}}
   string product=Arg("--product"),target=Path.GetFullPath(Arg("--target",AppDomain.CurrentDomain.BaseDirectory)),current=Arg("--current","0.0.0");if(!new[]{"photo","seewo"}.Contains(product)||!Directory.Exists(target))return 1;
   Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string lockName;using(var sha=SHA256.Create())lockName="Local\\ClassroomUpdater_"+BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(target.ToUpperInvariant()))).Replace("-","");bool created;using(var guard=new Mutex(true,lockName,out created)){if(!created){if(!args.Contains("--quiet"))MessageBox.Show("这个程序已有更新检查或安装窗口，请先完成现有操作。","课堂助教更新");return 0;}CleanCache(target,null,product,current);Application.Run(new UpdateForm(product,target,current,Arg("--pid"),args.Contains("--quiet")));}return 0;
  }
 }
 internal sealed class UpdateForm:Form {
  readonly string product,target,current,pid;readonly bool quiet;readonly Label status=new Label{AutoSize=true,MaximumSize=new Size(640,0),Font=new Font("Microsoft YaHei",16)};readonly Button install=new Button{Text="下载并更新",AutoSize=true,Font=new Font("Microsoft YaHei",16)};
   Dictionary<string,object> release;bool working,finished;
  public UpdateForm(string p,string t,string c,string parent,bool q){product=p;target=t;current=c;pid=parent;quiet=q;if(quiet){Opacity=0;ShowInTaskbar=false;}Text="课堂助教 · 云端更新";Width=730;Height=310;StartPosition=FormStartPosition.CenterScreen;var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(22),WrapContents=false};Controls.Add(panel);panel.Controls.Add(status);panel.Controls.Add(install);install.Enabled=false;install.Click+=async(_,__)=>await Install();Shown+=async(_,__)=>await Check();FormClosing+=(_,e)=>{if(working)e.Cancel=true;};}
  async Task Check(){if(quiet){Opacity=0;ShowInTaskbar=false;}status.Text="正在检查云端版本…";try{if(string.IsNullOrWhiteSpace(Program.Host)){if(quiet){Close();return;}status.Text="开源版尚未配置自己的更新服务，请从项目仓库手动更新，或设置 CLASSROOM_UPDATE_SERVER_URL 和 CLASSROOM_UPDATE_PUBLIC_KEY_PATH。";return;}using(var http=new HttpClient{Timeout=TimeSpan.FromSeconds(12)}){var data=Program.Verify(await http.GetStringAsync(Program.Host+"/updates/manifest.json?at="+DateTime.UtcNow.Ticks));release=(Dictionary<string,object>)data[product];var latest=Version.Parse((string)release["version"]);if(latest<=Version.Parse(current)){if(quiet){Close();return;}status.Text="已是当前发布版本（"+current+"）。";return;}status.Text="发现 "+release["version"]+"（当前 "+current+"）。\n"+release["notes"]+"\n更新保留本机接口配置和账号绑定。";Opacity=1;ShowInTaskbar=true;install.Enabled=true;}}catch(Exception e){if(quiet){Close();return;}status.Text="暂时无法检查更新，原程序可继续使用。\n"+e.Message;}}
  async Task Install(){if(release==null||working||finished)return;working=true;install.Enabled=false;string cache=Path.Combine(target,".update-cache"),stage=Path.Combine(cache,Guid.NewGuid().ToString("N"));bool launched=false;try{Directory.CreateDirectory(stage);status.Text="正在下载并验证更新…";byte[] bytes;using(var handler=new HttpClientHandler{AllowAutoRedirect=false})using(var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(90)}){using(var response=await http.GetAsync(Program.SafeUrl((string)release["url"]),HttpCompletionOption.ResponseHeadersRead)){response.EnsureSuccessStatusCode();long size=Convert.ToInt64(release["bytes"]);if(size<=0||size>40000000)throw new InvalidDataException("更新大小无效");using(var stream=await response.Content.ReadAsStreamAsync())using(var memory=new MemoryStream()){byte[] buffer=new byte[32768];int n;while((n=await stream.ReadAsync(buffer,0,buffer.Length))>0){if(memory.Length+n>size)throw new InvalidDataException("下载大小与签名清单不符");memory.Write(buffer,0,n);}bytes=memory.ToArray();if(bytes.Length!=size)throw new InvalidDataException("下载不完整");}}}
   using(var sha=SHA256.Create()){string hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();if(hash!=(string)release["sha256"])throw new InvalidDataException("文件校验失败，保留旧版");}
   var archive=Path.Combine(stage,"release.zip");File.WriteAllBytes(archive,bytes);var files=Program.Extract(archive,stage,product);File.WriteAllLines(Path.Combine(stage,"release.version"),new[]{product,(string)release["version"]});
    if(product=="seewo"){File.WriteAllText(Path.Combine(stage,"installer.pending"),"not confirmed installed");status.Text="已验证安装包。请先保存课件，正常退出希沃，再完成安装并重开。";MessageBox.Show(this,"请保存课件并退出希沃。即将打开希沃插件安装器，完成安装后重开希沃。已有模型密钥与手机绑定保留。","安装新版",MessageBoxButtons.OK,MessageBoxIcon.Information);Process.Start(new ProcessStartInfo(Path.Combine(stage,files.Single())){UseShellExecute=true});finished=true;status.Text="已打开希沃安装器，尚未确认安装成功。\n请完成安装并重开希沃，核对助教标题版本为 "+release["version"]+"。\n若取消安装，关闭本窗口后可重新检查更新。";install.Text="请完成安装并重开希沃";return;}
   if(MessageBox.Show(this,"更新将正常关闭拍照解题助教，保留现有接口配置并自动重开。当前题目和对话不跨更新保存，是否继续？","应用更新",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return;
   await ProcessLifecycle.WaitForOriginalExit(pid,Path.Combine(target,"拍照解题助教.exe"));
    Program.Apply(stage,target,files);finished=true;install.Text="已更新";Program.TrimBackups(target);status.Text="程序文件已更新，接口配置已保留。";try{using(var launchedProcess=await ProcessLifecycle.StartAndCheck(Path.Combine(target,"拍照解题助教.exe"))){launched=true;}status.Text="更新完成，已重新启动。请核对主窗口版本为 "+release["version"]+"。";}catch(Exception startError){status.Text="文件更新完成，但未能自动启动。请手动打开拍照解题助教。\n"+startError.Message;}
   }catch(Exception e){try{File.WriteAllText(Path.Combine(stage,"preserve.failed"),e.Message,Encoding.UTF8);}catch{}status.Text="更新未完成。\n"+e.Message+"\n"+(Directory.Exists(stage)?"失败现场保留："+stage:"目标目录不能创建更新缓存，未替换程序；请移到当前用户可写目录后重试。");}finally{working=false;install.Enabled=!finished;if(product=="photo"&&finished)try{Directory.Delete(stage,true);}catch{}if(launched)Close();} }
 }
}
